from scapy.all import PcapReader, IP, TCP, UDP
from collections import defaultdict,Counter
srcdstports=defaultdict(lambda: defaultdict(Counter))
for pkt in PcapReader('/root/packets.pcap'):
    if IP in pkt and (TCP in pkt or UDP in pkt):
        ip=pkt[IP]; s=ip.src; d=ip.dst
        p=pkt[TCP] if TCP in pkt else pkt[UDP]
        srcdstports[s][d][p.dport]+=1
for s in ['192.168.3.30','192.168.3.34','192.168.3.29']:
    print('SRC',s)
    for d,c in sorted(srcdstports[s].items(), key=lambda kv: sum(kv[1].values()), reverse=True)[:5]:
        print(' dst',d,'ports',len(c),'top',c.most_common(10))
